/* Flash cards USMLE: Psychiatry (448 cartões originais). [id, pergunta, resposta, explicação em português] */
window.USMLE_DATA = window.USMLE_DATA || {};
window.USMLE_DATA["psychiatry"] = [{"name":"Pathology (Part 1)","cards":[["1piqm2v38","What is schizophrenia?","Chronic psychotic disorder with ≥2 of: delusions, hallucinations, disorganized speech, disorganized or catatonic behavior, negative symptoms (at least one of the first three); ≥6 months with functional decline.","Psicose crônica por mais de 6 meses."],["1cd0d36qm","What are the positive symptoms of schizophrenia?","Hallucinations (usually auditory), delusions, disorganized speech and behavior.","Alucinações e delírios."],["1250j9mmf","What are the negative symptoms of schizophrenia?","Flat affect, avolition, alogia, anhedonia, asociality (5 As).","Afeto embotado, apatia, alogia."],["1vnn4d81n","What is the dopamine hypothesis of schizophrenia?","Excess mesolimbic dopamine (positive symptoms), decreased mesocortical dopamine (negative symptoms).","Excesso de dopamina mesolímbica."],["yixm3dc8r","What brain findings are associated with schizophrenia?","Lateral ventricular enlargement, decreased cortical volume.","Ventrículos aumentados."],["40e9fxoi3","What are risk factors for schizophrenia?","Family history, cannabis use in adolescence, urban birth, winter birth, prenatal infection, advanced paternal age.","Genética e maconha na adolescência."],["1rxoe8420","What is the typical age of onset of schizophrenia?","Men 18-25, women 25-35.","Homens mais cedo."],["1l5tbfkxq","What is brief psychotic disorder?","Psychotic symptoms lasting 1 day to <1 month, often after stress, with return to baseline.","Psicose de menos de 1 mês."],["b3ctggugp","What is schizophreniform disorder?","Schizophrenia symptoms lasting 1-6 months.","Psicose entre 1 e 6 meses."],["6yinx3opw","What is schizoaffective disorder?","Schizophrenia with major mood episodes, plus ≥2 weeks of psychosis without mood symptoms.","Esquizofrenia com episódios de humor."],["1bdxdisdh","What is delusional disorder?","≥1 delusion lasting ≥1 month without other psychotic symptoms; functioning relatively preserved.","Delírio isolado com função preservada."],["1pzelo71t","What is shared psychotic disorder (folie à deux)?","Delusion transmitted from one person to another closely associated person.","Delírio compartilhado."],["1ffpciweb","What are the types of hallucinations and their associations?","Auditory (schizophrenia), visual (delirium, drug intoxication, Lewy body), olfactory (temporal lobe epilepsy aura), tactile (alcohol withdrawal, cocaine bugs), hypnagogic and hypnopompic (narcolepsy).","Tipos de alucinação."],["ajbcua18t","What is an illusion vs hallucination?","Illusion: misperception of a real stimulus. Hallucination: perception without external stimulus.","Ilusão versus alucinação."],["8mpnfscti","What is a delusion?","Fixed false belief not shared by culture, persisting despite contrary evidence.","Crença falsa fixa."],["1imucqw9t","What is a loose association?","Disorganized speech with shifting topics without logical connection.","Afrouxamento de associações."],["mw1uap11p","What is catatonia and its treatment?","Stupor, mutism, posturing, waxy flexibility, negativism, echolalia; treat with benzodiazepines (lorazepam) or ECT.","Catatonia; lorazepam."],["akduwt1xp","What is major depressive disorder?","≥5 of SIG E CAPS for ≥2 weeks including depressed mood or anhedonia: Sleep, Interest, Guilt, Energy, Concentration, Appetite, Psychomotor changes, Suicidal ideation.","Depressão maior; SIG E CAPS."],["u8qzxw2la","What are atypical depression features?","Mood reactivity, hypersomnia, hyperphagia, leaden paralysis, sensitivity to rejection; responds to MAOIs historically, SSRIs.","Hipersonia e aumento do apetite."],["1w8urv04v","What is persistent depressive disorder (dysthymia)?","Depressed mood most days for ≥2 years, milder than major depression.","Depressão leve crônica por 2 anos."],["1j4pwxn17","What is seasonal affective disorder?","Depression with seasonal pattern (winter); treat with bright light therapy, SSRIs.","Depressão no inverno; fototerapia."],["16j33nbpb","What is premenstrual dysphoric disorder?","Mood symptoms in the luteal phase, resolving after menses; treat with SSRIs, OCPs.","Disforia pré-menstrual."],["1d91he5db","What are postpartum mood disturbances?","Baby blues (≤2 weeks, mild), postpartum depression (≥2 weeks, within 4 weeks of delivery, treat), postpartum psychosis (emergency, risk of infanticide).","Tristeza pós-parto, depressão e psicose."],["1r3ff6vh7","What is the treatment of postpartum depression?","CBT, SSRIs, zuranolone or brexanolone (neurosteroids).","Psicoterapia, ISRS, zuranolona."],["1fdfg531b","What is electroconvulsive therapy used for?","Treatment-resistant depression, depression with psychotic features, catatonia, acute suicidality, depression in pregnancy.","Depressão resistente e catatonia."],["1ets2qasf","What are the adverse effects of ECT?","Anterograde and retrograde amnesia (usually resolves), headache; no absolute contraindications (caution with recent MI, increased ICP).","Amnésia transitória."],["10ox1pepy","What is a manic episode?","Abnormally elevated, expansive, or irritable mood with increased energy ≥1 week (or hospitalization) and ≥3 DIG FAST: Distractibility, Impulsivity/Indiscretion, Grandiosity, Flight of ideas, Activity increase, Sleep decreased, Talkativeness.","Mania; DIG FAST."],["261oj0dka","What is a hypomanic episode?","Like mania but ≥4 days, no marked impairment, no psychosis, no hospitalization.","Hipomania mais leve."],["1mkg06018","What is bipolar I disorder?","At least one manic episode (depression not required).","Pelo menos um episódio maníaco."],["1u4ytip1k","What is bipolar II disorder?","At least one hypomanic and one major depressive episode, no mania.","Hipomania e depressão."],["1g0gele1m","What is cyclothymic disorder?","Fluctuating hypomanic and depressive symptoms not meeting full criteria for ≥2 years.","Oscilações leves por 2 anos."],["1dy7hkc1k","Treatment of bipolar disorder?","Mood stabilizers (lithium, valproate, carbamazepine, lamotrigine) and atypical antipsychotics.","Lítio, valproato, antipsicóticos."],["fsjzrd2lf","Why should antidepressants not be used alone in bipolar disorder?","Risk of inducing mania.","Risco de virada maníaca."],["156r0ncoa","What is generalized anxiety disorder?","Excessive anxiety and worry most days for ≥6 months about multiple activities, with restlessness, irritability, sleep disturbance, fatigue, tension.","Preocupação excessiva por 6 meses."],["ernknpqgq","Treatment of generalized anxiety disorder?","CBT, SSRIs, SNRIs, buspirone; benzodiazepines short term.","Terapia, ISRS, buspirona."],["1xeucwfbh","What is panic disorder?","Recurrent unexpected panic attacks with ≥1 month of worry about attacks or behavior change.","Ataques de pânico recorrentes com medo de novos."],["1vzpepphl","Symptoms of a panic attack?","Palpitations, chest pain, sweating, shaking, dyspnea, choking, nausea, dizziness, paresthesias, fear of dying, derealization; peak in 10 minutes.","Palpitações, falta de ar, medo de morrer."],["avfqqa1c2","Treatment of panic disorder?","CBT, SSRIs, SNRIs; benzodiazepines for acute attacks.","Terapia e ISRS."],["1s2r9ot1j","What is agoraphobia?","Fear of places where escape may be difficult (public transportation, crowds, being outside alone).","Medo de lugares sem saída fácil."],["cmmlfb7bs","What is specific phobia?","Intense fear of a specific object or situation (heights, animals); treat with exposure therapy.","Fobia específica."],["kkacgnxos","What is social anxiety disorder?","Fear of social situations with scrutiny; treat with CBT, SSRIs; performance-only type: beta-blockers.","Fobia social."],["1pow603s4","What is selective mutism?","Failure to speak in certain situations despite speaking normally in others (children).","Mutismo seletivo."],["1aj8h0gt8","What is separation anxiety disorder?","Excessive fear of separation from attachment figures beyond developmental expectations.","Ansiedade de separação."],["1woe8vr1j","What is obsessive-compulsive disorder?","Recurrent intrusive thoughts (obsessions) and repetitive behaviors (compulsions) to reduce anxiety; ego-dystonic; associated with Tourette syndrome.","Obsessões e compulsões egodistônicas."],["1p2svb3y9","Treatment of OCD?","CBT (exposure and response prevention), SSRIs (high doses), clomipramine.","Terapia de exposição e ISRS."],["1ooayp21x","What is body dysmorphic disorder?","Preoccupation with perceived physical flaws not observable to others, with repetitive behaviors.","Preocupação com defeito imaginário."],["1enyk2y1e","What is hoarding disorder?","Persistent difficulty discarding possessions, causing clutter.","Acumulação."],["rmntix1fg","What is trichotillomania?","Compulsively pulling out one's hair causing hair loss.","Arrancar os cabelos."],["10om359hh","What is excoriation disorder?","Recurrent skin picking.","Escoriação compulsiva."],["wackk91us","What is PTSD?","Exposure to trauma followed by intrusion (flashbacks, nightmares), avoidance, negative mood/cognition, hyperarousal for >1 month.","Estresse pós-traumático por mais de 1 mês."],["nhq0do1ow","What is acute stress disorder?","PTSD-like symptoms lasting 3 days to 1 month after trauma.","Sintomas entre 3 dias e 1 mês."],["r14sas1tb","Treatment of PTSD?","Trauma-focused CBT, SSRIs, SNRIs; prazosin for nightmares.","Terapia e ISRS; prazosina para pesadelos."],["6nk06txu5","What is adjustment disorder?","Emotional or behavioral symptoms within 3 months of an identifiable stressor, lasting <6 months after the stressor ends.","Reação a estressor."],["e43hbsj7w","What is reactive attachment disorder?","Withdrawn behavior in children after severe neglect (do not seek comfort).","Criança retraída por negligência."],["711ly27hg","What is disinhibited social engagement disorder?","Overly familiar behavior with strangers after neglect.","Familiaridade excessiva com estranhos."],["vgmhw73uv","What is depersonalization/derealization disorder?","Persistent feelings of detachment from oneself or surroundings with intact reality testing.","Despersonalização."],["1o9cab5de","What is dissociative amnesia?","Inability to recall autobiographical information after trauma; dissociative fugue is travel with amnesia.","Amnésia dissociativa."],["ap98uj81x","What is dissociative identity disorder?","Two or more distinct identities; associated with severe childhood trauma.","Múltiplas identidades."],["t7jak51fd","What is somatic symptom disorder?","One or more somatic symptoms with excessive thoughts, anxiety, or behavior about them for >6 months.","Preocupação excessiva com sintomas."],["wpinri9eh","What is illness anxiety disorder?","Excessive preoccupation with having a serious illness with minimal or no symptoms.","Medo de ter doença grave."],["k78hf4bkq","What is conversion disorder (functional neurologic symptom disorder)?","Neurologic symptoms (paralysis, blindness, seizures) inconsistent with neurologic disease, often after stress; la belle indifférence.","Sintomas neurológicos sem doença."],["16gda1fvo","What is factitious disorder imposed on self (Munchausen)?","Intentionally faking or inducing illness for the sick role (primary gain).","Munchausen."],["m9svgzu02","What is factitious disorder imposed on another (Munchausen by proxy)?","Caregiver induces illness in another (often child); considered abuse.","Munchausen por procuração."],["1mg2kbh7m","What is malingering?","Faking symptoms for external gain (money, avoiding work or jail).","Simulação por ganho externo."],["ft9knq1qe","What is the management of somatic symptom disorder?","Regular scheduled visits with one physician, limit unnecessary tests, CBT.","Consultas regulares com um médico."],["to9rg3361","What is a depressive episode with psychotic features?","Depression with mood-congruent delusions or hallucinations; treat with antidepressant plus antipsychotic or ECT.","Depressão psicótica."],["1kgy1k310","What is the role of lithium in suicide prevention?","Lithium reduces suicide risk in bipolar disorder and depression.","Lítio reduz suicídio."],["1rnyif018","What is the mechanism of ketamine in depression?","NMDA antagonist with rapid antidepressant effect (esketamine nasal spray for treatment-resistant depression).","Efeito antidepressivo rápido."],["6avuttuii","What is the duration of antidepressant therapy after a first major depressive episode?","Continue at least 6-12 months after remission.","Pelo menos 6 a 12 meses."],["7gdgaq13v","How long do SSRIs take to work?","About 4-8 weeks for full effect.","4 a 8 semanas."],["1qscw2i1m","What medical conditions can mimic depression?","Hypothyroidism, Cushing, Parkinson, stroke, pancreatic cancer, vitamin deficiencies, medications (beta-blockers, interferon, steroids).","Hipotireoidismo e outras causas."],["widq0y123","What medical conditions can mimic anxiety?","Hyperthyroidism, pheochromocytoma, arrhythmias, hypoglycemia, stimulant use, caffeine, alcohol withdrawal.","Hipertireoidismo e feocromocitoma."],["w42gsj3gm","What medical conditions can mimic psychosis?","Delirium, drug intoxication, brain tumors, temporal lobe epilepsy, SLE, Wilson disease, anti-NMDA receptor encephalitis, HIV.","Delirium, drogas, tumores."],["8un3b8kv2","What is anti-NMDA receptor encephalitis?","Autoimmune encephalitis (often with ovarian teratoma): psychosis, seizures, dyskinesias, autonomic instability.","Encefalite com psicose; teratoma."],["13si7hgpq","What is the duration requirement for schizophrenia vs schizophreniform vs brief psychotic?","Schizophrenia ≥6 months; schizophreniform 1-6 months; brief psychotic <1 month.","Duração define o diagnóstico."],["1ox2g1nyy","What is the prognosis predictor in schizophrenia?","Better: later onset, acute onset, positive symptoms, mood symptoms, good premorbid function, female. Worse: early insidious onset, negative symptoms.","Prognóstico."],["10cdjttuc","What is the leading cause of death in schizophrenia?","Cardiovascular disease and suicide (higher rates).","Doença cardiovascular e suicídio."],["x4kyfd1cz","What is pseudodementia?","Cognitive impairment due to depression in elderly, improves with treatment.","Demência pela depressão."],["i1t91hiil","What is the mood disorder risk with corticosteroids?","Mania, psychosis, depression.","Mania e psicose."],["duet6u361","What is the mood disorder risk with isotretinoin?","Depression and suicidal ideation.","Depressão."],["1l9arzamq","What is the mood disorder risk with interferon-alpha?","Depression.","Depressão."],["13zc3ulo8","What is the anxiety disorder with fear of contamination and repeated handwashing?","OCD.","Transtorno obsessivo-compulsivo."],["26sy9d1u0","What is the anxiety disorder with fear of being judged when giving a speech?","Social anxiety disorder (performance only).","Fobia social de desempenho."],["1airl34xm","What is the treatment for performance-only social anxiety?","Beta-blockers (propranolol) before the event.","Propranolol antes do evento."],["j4p2ie15h","What is panic disorder with cardiac workup?","Rule out MI, arrhythmia, hyperthyroidism before diagnosing panic disorder.","Excluir causas cardíacas."],["ds8f121iq","What is the prevalence pattern of major depression?","More common in women (2:1).","Duas vezes mais em mulheres."],["oycsyg1va","What is the prevalence pattern of bipolar disorder?","Equal in men and women.","Igual nos sexos."],["sq18ob10d","What sleep changes occur in depression?","Decreased REM latency, increased REM density, decreased slow-wave sleep, early morning awakening.","REM precoce e despertar cedo."],["7itbegewd","What is the hypothalamic-pituitary-adrenal axis change in depression?","Increased cortisol (failure to suppress with dexamethasone).","Cortisol elevado."],["1iwnin9al","What neurotransmitter changes are associated with depression?","Decreased serotonin, norepinephrine, dopamine.","Menos serotonina e noradrenalina."],["1fcj21p23","What neurotransmitter changes are associated with anxiety?","Increased norepinephrine, decreased GABA and serotonin.","Mais noradrenalina; menos GABA."],["c2otc01xp","What is the treatment for acute mania?","Antipsychotics (atypical), lithium, valproate; benzodiazepines for agitation.","Antipsicótico e estabilizador do humor."],["w1msgatwx","What is rapid cycling bipolar disorder?","≥4 mood episodes in one year; valproate and lamotrigine may be preferred.","Quatro ou mais episódios por ano."],["175q0xfr5","What is the best maintenance therapy for bipolar depression?","Lamotrigine, quetiapine, lurasidone, lithium.","Lamotrigina e quetiapina."],["x9ccl9pq1","What is mixed features in mood disorders?","Manic and depressive symptoms at the same time; higher suicide risk.","Sintomas maníacos e depressivos juntos."],["uyuov46vu","What is psychosis due to stimulant intoxication?","Paranoia, hallucinations (often tactile), agitation with sympathomimetic signs.","Psicose por estimulantes."],["fkdeey1w0","What is psychosis due to hallucinogens?","Visual hallucinations, synesthesia, normal vital signs (LSD), with intact orientation.","Alucinações visuais por LSD."],["1bgum1uek","What is the key difference between delirium and psychosis?","Delirium: impaired attention and consciousness, fluctuating, visual hallucinations. Primary psychosis: clear sensorium.","Delirium altera a consciência."],["9j7ql51ur","What is the treatment of delirium?","Treat underlying cause, reorientation, sleep hygiene; low-dose antipsychotics (haloperidol) if agitated; avoid benzodiazepines (except alcohol withdrawal).","Tratar a causa; evitar benzodiazepínicos."],["1dz7plun5","What is the treatment of insomnia in older adults?","CBT-I first; avoid benzodiazepines and anticholinergics.","Terapia cognitiva para insônia."],["1xpvw9hyq","What is the mental status exam components?","Appearance, behavior, speech, mood (patient's words), affect (observed), thought process, thought content, perception, cognition, insight, judgment.","Componentes do exame mental."],["1rajuzj1q","What is the difference between mood and affect?","Mood: patient's subjective emotional state. Affect: observed emotional expression.","Humor relatado; afeto observado."],["gl4jk117n","What is flight of ideas?","Rapid speech with abrupt shifts between loosely connected topics (mania).","Fuga de ideias."],["1gnq0cj1e","What is pressured speech?","Rapid, hard-to-interrupt speech (mania).","Fala pressionada."],["tum1b21hw","What is thought blocking?","Sudden interruption of thought (schizophrenia).","Bloqueio do pensamento."],["19nrkmr1c","What is tangentiality vs circumstantiality?","Tangential: wanders and never returns to the point. Circumstantial: wanders but eventually returns.","Tangencial nunca volta; circunstancial volta."],["17yib101k","What is clang association?","Words chosen by sound rather than meaning (rhyming), seen in mania or psychosis.","Associação por som."],["ymiu8t1np","What is neologism?","Invented words (schizophrenia).","Palavras inventadas."],["16n8zhb9a","What is word salad?","Incoherent jumble of words (severe psychosis).","Salada de palavras."],["ejg9on7ec","What is perseveration?","Repetition of the same response regardless of the question (frontal lobe, dementia).","Perseveração."],["12be8seii","What are ideas of reference?","Belief that unrelated events have special personal meaning (TV speaking to them).","Ideias de referência."],["17hcznn15","What are delusions of grandeur?","Belief of having special powers or importance (mania).","Delírio de grandeza."],["w3bxa9124","What are persecutory delusions?","Belief one is being harmed or watched (paranoid schizophrenia).","Delírio persecutório."],["z2wzwj1hm","What is erotomania?","Delusion that someone (often famous) is in love with them.","Erotomania."],["1kt47ba15","What is a nihilistic delusion?","Belief one is dead or body parts do not exist (Cotard, severe depression).","Delírio niilista."],["7hnfxmxm4","What is Capgras syndrome?","Delusion that a close person has been replaced by an impostor.","Síndrome de Capgras."],["h4p6rqrax","What is a somatic delusion?","False belief about one's body (infestation, bodily dysfunction).","Delírio somático."],["1o370261g","What is delusional parasitosis?","Fixed belief of skin infestation with parasites despite no evidence.","Delírio de infestação."],["1uvm7ffwg","What is the difference between an obsession and a delusion?","Obsessions are recognized as unreasonable (ego-dystonic); delusions are firmly believed.","Obsessão é reconhecida como irracional."],["kcgkg51d8","What is anhedonia?","Loss of interest or pleasure in activities.","Perda de prazer."],["1lg7opi1u","What is psychomotor retardation?","Slowed thinking and movement, seen in severe depression.","Lentificação psicomotora."],["16y6jp51v","What is the definition of a mixed anxiety-depression presentation's first-line drug?","SSRIs (treat both).","ISRS."],["du4fbr1ta","What is the strongest risk factor for postpartum psychosis?","History of bipolar disorder.","Transtorno bipolar prévio."]]},{"name":"Pathology (Part 2)","cards":[["1tr8h3bj9","What is a personality disorder?","Enduring, inflexible, maladaptive pattern of behavior and inner experience deviating from cultural norms, starting in adolescence or early adulthood; usually ego-syntonic.","Padrão rígido e egossintônico."],["11enx4b19","What are the cluster A personality disorders?","Paranoid, schizoid, schizotypal (weird); associated with family history of schizophrenia.","Grupo A: estranhos."],["10vk36w1b","What is paranoid personality disorder?","Pervasive distrust and suspicion of others; projection as defense.","Desconfiança generalizada."],["1qdjdvzjv","What is schizoid personality disorder?","Detachment from social relationships, restricted emotional expression, prefers being alone (no desire for relationships).","Isolamento sem desejo de relações."],["nckj1u1m7","What is schizotypal personality disorder?","Eccentric appearance, odd beliefs or magical thinking, interpersonal awkwardness, ideas of reference.","Excêntrico com pensamento mágico."],["9g991k1r2","What are the cluster B personality disorders?","Antisocial, borderline, histrionic, narcissistic (wild); associated with mood and substance disorders.","Grupo B: dramáticos."],["1k7v0wfl1","What is antisocial personality disorder?","Disregard for and violation of rights of others, criminality, impulsivity; ≥18 years with conduct disorder before 15; more common in males.","Desrespeito aos direitos dos outros."],["1swlvj81w","What is borderline personality disorder?","Unstable mood and relationships, impulsivity, self-mutilation, suicidality, fear of abandonment, splitting; more common in females.","Instabilidade, impulsividade, medo de abandono."],["50h8gpd2v","Treatment of borderline personality disorder?","Dialectical behavior therapy.","Terapia comportamental dialética."],["1yu5sogn7","What is histrionic personality disorder?","Attention seeking, excessive emotionality, sexually provocative behavior, shallow emotions.","Busca de atenção e dramaticidade."],["4zjzmdqer","What is narcissistic personality disorder?","Grandiosity, sense of entitlement, lack of empathy, need for admiration; fragile self-esteem.","Grandiosidade e falta de empatia."],["9jnh611ek","What are the cluster C personality disorders?","Avoidant, obsessive-compulsive, dependent (worried); associated with anxiety disorders.","Grupo C: ansiosos."],["1its3wozb","What is avoidant personality disorder?","Hypersensitivity to rejection, feelings of inadequacy, social inhibition despite desire for relationships.","Evita por medo de rejeição."],["1nca0izyo","What is obsessive-compulsive personality disorder?","Preoccupation with order, perfectionism, control; ego-syntonic (unlike OCD).","Perfeccionismo egossintônico."],["moezbb1tt","What is dependent personality disorder?","Excessive need to be taken care of, submissive, clingy; difficulty making decisions.","Dependência excessiva."],["933si8by1","How does schizoid differ from avoidant personality disorder?","Schizoid: no desire for relationships. Avoidant: wants relationships but fears rejection.","Esquizoide não quer; evitativo tem medo."],["4wd38zw2v","What is substance use disorder?","Maladaptive pattern of use with impaired control, social impairment, risky use, tolerance, withdrawal (≥2 criteria in 12 months).","Uso problemático de substâncias."],["1g7dlh2v7","What are signs of alcohol intoxication?","Disinhibition, ataxia, slurred speech, nystagmus, blackouts, coma, respiratory depression.","Desinibição, ataxia, fala arrastada."],["1mc4ylg4n","What is the timeline of alcohol withdrawal?","Tremors and anxiety within 6-24 hours; hallucinations 12-48 hours; seizures 12-48 hours; delirium tremens 48-96 hours.","Abstinência alcoólica em etapas."],["1x3dtyz11","What is delirium tremens?","Life-threatening alcohol withdrawal with confusion, autonomic hyperactivity, hallucinations, 2-4 days after last drink.","Forma grave e potencialmente fatal."],["1m4kz9u1v","Treatment of alcohol withdrawal?","Benzodiazepines (long-acting chlordiazepoxide, diazepam; lorazepam or oxazepam in liver disease), thiamine.","Benzodiazepínicos e tiamina."],["164vpny17","Treatment of alcohol use disorder?","Naltrexone, acamprosate, disulfiram, topiramate, gabapentin; psychotherapy, support groups.","Naltrexona e acamprosato."],["1rytmeps4","Lab findings of chronic alcohol use?","Elevated GGT, AST:ALT >2, macrocytosis (high MCV), carbohydrate-deficient transferrin.","GGT alta e VCM alto."],["1klceso30","What are signs of opioid intoxication?","Euphoria, respiratory depression, miosis, constipation, drowsiness.","Miose e depressão respiratória."],["vs8zqs1o5","What are signs of opioid withdrawal?","Sweating, dilated pupils, piloerection (cold turkey), yawning, rhinorrhea, lacrimation, diarrhea, nausea, abdominal cramps; not life-threatening.","Midríase, piloereção, diarreia."],["10zjhio1m","Treatment of opioid use disorder?","Methadone, buprenorphine, naltrexone; naloxone for overdose.","Metadona e buprenorfina."],["c6k5vp3xu","What are signs of benzodiazepine or barbiturate intoxication?","Drowsiness, ataxia, respiratory depression (barbiturates more dangerous).","Sonolência e ataxia."],["1wl00rhnl","What are signs of benzodiazepine withdrawal?","Anxiety, tremor, insomnia, seizures, delirium; potentially life-threatening.","Ansiedade, tremor e convulsões."],["1622wj4ts","What are signs of cocaine intoxication?","Euphoria, agitation, tachycardia, hypertension, mydriasis, hallucinations (formication), chest pain (MI), seizures.","Agitação, taquicardia, midríase."],["130o8x870","What are signs of cocaine withdrawal?","Crash: hypersomnolence, hyperphagia, depression, fatigue, nightmares, suicidality.","Sono e depressão."],["10nev93cm","What are signs of amphetamine intoxication?","Euphoria, agitation, hypertension, tachycardia, mydriasis, psychosis, seizures, hyperthermia.","Semelhante à cocaína."],["195xwhruj","What are signs of PCP intoxication?","Violence, impulsivity, psychomotor agitation, vertical and horizontal nystagmus, hypertension, tachycardia, analgesia, psychosis.","Violência e nistagmo vertical."],["1ap6nc7w2","What are signs of LSD intoxication?","Perceptual distortions (visual), depersonalization, anxiety, paranoia, flashbacks; tachycardia, mydriasis.","Alucinações visuais."],["1266c7u89","What are signs of marijuana intoxication?","Euphoria, anxiety, conjunctival injection, increased appetite, dry mouth, impaired coordination, slowed time perception.","Olhos vermelhos e fome."],["15mpzwpfh","What is cannabinoid hyperemesis syndrome?","Cyclic vomiting in chronic cannabis users, relieved by hot showers.","Vômitos que melhoram com banho quente."],["dgxr3x1mz","What are signs of nicotine withdrawal?","Irritability, anxiety, increased appetite, weight gain, insomnia, cravings.","Irritabilidade e fome."],["18bndo937","Treatment of nicotine dependence?","Nicotine replacement, varenicline, bupropion.","Reposição de nicotina e vareniclina."],["1d1exl11x","What are signs of caffeine withdrawal?","Headache, fatigue, depression, irritability.","Dor de cabeça e fadiga."],["lwh1udujw","What are signs of MDMA (ecstasy) intoxication?","Euphoria, hyperthermia, hyponatremia (SIADH and water intake), bruxism, serotonin syndrome, rhabdomyolysis.","Hipertermia e hiponatremia."],["qus0md4c9","What are signs of inhalant intoxication?","Disinhibition, euphoria, slurred speech, ataxia, perioral rash; sudden death from arrhythmia.","Inalantes; morte súbita."],["kefjtxnti","What are signs of synthetic cathinone (bath salts) intoxication?","Agitation, psychosis, hyperthermia, sympathomimetic toxidrome.","Agitação e psicose."],["1600ugvdt","What is anorexia nervosa?","Restriction of energy intake leading to significantly low body weight, intense fear of weight gain, distorted body image; restricting or binge-purge type.","Restrição com peso muito baixo."],["ztct271os","Complications of anorexia nervosa?","Amenorrhea, bradycardia, hypotension, osteoporosis, lanugo, hypothermia, cardiac arrhythmias, refeeding syndrome, increased cortisol, euthyroid sick syndrome.","Amenorreia, bradicardia, osteoporose."],["1q7fxnm1j","Treatment of anorexia nervosa?","Nutritional rehabilitation, psychotherapy (family-based), olanzapine for weight gain in some.","Reabilitação nutricional e terapia familiar."],["fckrf36sw","What is bulimia nervosa?","Recurrent binge eating with compensatory behaviors (vomiting, laxatives, exercise) at least weekly for 3 months; normal or above-normal weight.","Compulsão com compensação; peso normal."],["141253ql6","Signs of bulimia nervosa?","Parotid enlargement, dental enamel erosion, Russell sign (knuckle calluses), hypokalemic hypochloremic metabolic alkalosis.","Parótidas aumentadas e sinal de Russell."],["1x4p7le1h","Treatment of bulimia nervosa?","CBT, SSRIs (fluoxetine); avoid bupropion (seizures).","Terapia e fluoxetina."],["m7887h142","What is binge eating disorder?","Recurrent binge eating without compensatory behaviors; increased obesity risk; treat with CBT, SSRIs, lisdexamfetamine.","Compulsão sem compensação."],["vpnh1t1vi","What is pica?","Persistent eating of nonfood substances; associated with iron deficiency, pregnancy, intellectual disability.","Comer coisas não alimentares."],["wn9nwj1v2","What is ADHD?","Inattention and/or hyperactivity-impulsivity, symptoms before age 12, in ≥2 settings for ≥6 months.","Desatenção e hiperatividade."],["qtit5q1t1","Treatment of ADHD?","Stimulants (methylphenidate, amphetamines), atomoxetine, guanfacine, clonidine; behavioral therapy.","Estimulantes e terapia."],["1i8teaepe","What is autism spectrum disorder?","Impaired social communication and restricted, repetitive behaviors or interests, beginning in early childhood; increased head size, associated with intellectual disability.","Prejuízo social e comportamentos repetitivos."],["t5foco15e","What is Rett syndrome?","X-linked (MECP2) disorder in girls: normal development until 6-18 months, then regression, stereotyped hand-wringing, seizures, ataxia.","Regressão em meninas; mãos em lavagem."],["dntvha15o","What is conduct disorder?","Repetitive violation of rights of others or societal norms in children (aggression, destruction, theft); can progress to antisocial personality after 18.","Violação de regras na infância."],["xj26mc1rh","What is oppositional defiant disorder?","Pattern of angry, irritable mood, argumentative and defiant behavior toward authority, without serious violations.","Desafio à autoridade."],["kg92z2gvt","What is disruptive mood dysregulation disorder?","Severe recurrent temper outbursts with persistently irritable mood in children 6-18.","Explosões de raiva frequentes."],["ru44eb1wv","What is Tourette disorder's comorbidities?","OCD and ADHD.","TOC e TDAH."],["78ftjvcko","Treatment of Tourette disorder?","Behavioral therapy, alpha2 agonists (guanfacine, clonidine), antipsychotics (aripiprazole).","Terapia e clonidina."],["18g1amish","What is enuresis?","Repeated urination into bed or clothes ≥2 times/week for 3 months after age 5; treat with alarms, desmopressin.","Xixi na cama após 5 anos."],["x693kz121","What is encopresis?","Repeated passage of feces in inappropriate places after age 4, often from constipation with overflow.","Escape de fezes."],["aylh2ullg","What is gender dysphoria?","Distress from incongruence between experienced gender and assigned sex.","Disforia de gênero."],["jq6y40134","What are paraphilic disorders?","Recurrent intense sexual urges or behaviors involving nonconsenting persons, objects, or suffering, causing distress or harm.","Parafilias."],["ale2mn8pb","What are sexual dysfunctions?","Desire disorders, arousal disorders (erectile dysfunction), orgasmic disorders, sexual pain disorders; consider drugs (SSRIs, antihypertensives) and medical causes.","Disfunções sexuais."],["14lcygnrv","What is the most common cause of sexual dysfunction from medications?","SSRIs (delayed orgasm, decreased libido).","ISRS."],["yj0pn914g","What is the difference between OCD and OCPD?","OCD: ego-dystonic obsessions and compulsions. OCPD: ego-syntonic perfectionism and control.","TOC egodistônico; personalidade egossintônica."],["1nwnmob10","What is the treatment of choice for antisocial personality disorder?","No effective treatment; manage comorbidities.","Sem tratamento eficaz."],["xxk650ys7","What is the risk of suicide in borderline personality disorder?","High; frequent self-harm and suicide attempts.","Alto risco."],["3fxksh94a","What is factitious disorder's typical patient profile?","Healthcare workers, with numerous hospitalizations and procedures.","Profissionais de saúde."],["yn3roy8yf","What is the difference between somatic symptom disorder and conversion disorder?","Somatic symptom: excessive concern about real symptoms. Conversion: neurologic deficits without organic cause.","Preocupação versus déficit neurológico."],["lx8vsp7f3","What is the treatment for opioid overdose with respiratory depression?","Naloxone IV, IM, or intranasal; support ventilation.","Naloxona e suporte ventilatório."],["1v7ox0rkn","What is the CIWA scale used for?","Assessing alcohol withdrawal severity to guide benzodiazepine dosing.","Gravidade da abstinência alcoólica."],["rrrbgfixz","What is the COWS scale used for?","Assessing opioid withdrawal severity.","Gravidade da abstinência de opioides."],["jit5h51rd","What is Wernicke-Korsakoff in alcoholics?","Thiamine deficiency: confusion, ophthalmoplegia, ataxia, then memory loss and confabulation.","Falta de tiamina."],["vqk6r8rss","What is alcoholic hallucinosis?","Visual, auditory, or tactile hallucinations 12-48 hours after last drink with normal vital signs and clear sensorium.","Alucinações com consciência clara."],["17moqice8","What is the treatment of cocaine-induced chest pain?","Benzodiazepines, aspirin, nitrates; avoid beta-blockers acutely.","Benzodiazepínicos e nitratos."],["151h8u1or","What is the treatment of PCP intoxication?","Benzodiazepines, rapid-acting antipsychotics for agitation; supportive.","Benzodiazepínicos."],["4fdh931pl","What is the screening tool for unhealthy alcohol use in adults?","AUDIT-C or single question (how many times in the past year have you had 5+/4+ drinks).","AUDIT-C."],["1qs9egyab","What is the definition of heavy drinking in men and women?","Men: >14 drinks/week or >4 per occasion. Women: >7 drinks/week or >3 per occasion.","Consumo pesado."],["1xfuqssva","What is fetal alcohol syndrome's psychiatric impact?","Intellectual disability, ADHD-like behavior, learning problems.","Deficiência intelectual e déficit de atenção."],["b4eqzdi17","What is a sign of chronic inhalant use?","Peripheral neuropathy, cerebellar damage, perioral 'huffer's rash'.","Neuropatia e lesões ao redor da boca."],["10esom3vu","What is a sign of chronic cocaine snorting?","Nasal septal perforation.","Perfuração do septo nasal."],["1w0iiv31u","What is a sign of chronic methamphetamine use?","Severe dental decay (meth mouth), skin picking sores, weight loss.","Dentes destruídos."],["12qp6es77","What is the most common psychiatric comorbidity in substance use disorders?","Depression and anxiety disorders.","Depressão e ansiedade."],["7l1h1fbnv","What is the psychiatric emergency of neuroleptic malignant syndrome vs serotonin syndrome vs malignant hyperthermia?","NMS: antipsychotics, rigidity. Serotonin: serotonergic drugs, clonus. MH: anesthetics, rigidity during surgery.","Causas diferentes de hipertermia."],["10vcqzxeu","What is lithium toxicity's presentation?","Coarse tremor, ataxia, confusion, nausea, vomiting, seizures; precipitated by dehydration, NSAIDs, ACE inhibitors, thiazides.","Tremor grosseiro e ataxia."],["1f3fmfv1r","What is the treatment of lithium toxicity?","IV fluids, hemodialysis for severe toxicity.","Hidratação e hemodiálise."],["1wttod83n","What is a common cause of hypersexuality in Parkinson disease?","Dopamine agonists (impulse control disorders).","Agonistas dopaminérgicos."],["m1xhaffix","What is the treatment of insomnia in depression?","Mirtazapine or trazodone (sedating antidepressants).","Mirtazapina ou trazodona."],["1a7fzgu8b","What is the main risk of untreated ADHD in adolescence?","Substance use, accidents, academic failure.","Uso de drogas e acidentes."],["6mvah5jdd","What is the first-line treatment for autism-associated irritability?","Risperidone or aripiprazole (plus behavioral therapy).","Risperidona ou aripiprazol."],["bf3fnw186","What is the gold standard therapy for autism spectrum disorder?","Applied behavior analysis and early intensive behavioral intervention.","Intervenção comportamental precoce."],["1oknnfn1x","What is the leading psychiatric cause of disability worldwide?","Major depressive disorder.","Depressão maior."],["qpgmh2rnj","What is the most common psychiatric disorder in the US?","Anxiety disorders (specific phobia most common).","Transtornos de ansiedade."],["v1ilee1ph","What is the most common psychiatric disorder in elderly?","Depression (often underdiagnosed), anxiety; dementia is common neurocognitive disorder.","Depressão."],["ug897x1r8","What is the difference between insight and judgment?","Insight: awareness of one's illness. Judgment: ability to make sound decisions.","Consciência da doença versus decisões."],["1cg7ewk1t","What is the treatment for social anxiety disorder (generalized)?","CBT and SSRIs or SNRIs.","Terapia e ISRS."],["wr8q1dfzb","What is the treatment for specific phobia?","Exposure therapy (systematic desensitization).","Dessensibilização sistemática."],["qbpz4cxzk","What is the treatment for hoarding disorder?","CBT; SSRIs may help.","Terapia cognitiva."],["kek4yn1um","What is the treatment for trichotillomania?","Habit reversal therapy, N-acetylcysteine, SSRIs.","Terapia de reversão de hábito."],["ueptkwf5n","What is the treatment for body dysmorphic disorder?","CBT and SSRIs.","Terapia e ISRS."],["1bk06js95","What is the treatment for illness anxiety disorder?","CBT, regular visits with one physician, SSRIs.","Terapia e consultas regulares."],["1avgn6b1i","What is the treatment for adjustment disorder?","Psychotherapy (supportive, CBT).","Psicoterapia."],["1kcw88be0","What is the treatment for PTSD nightmares?","Prazosin.","Prazosina."],["sfzmg01ly","What is a key psychiatric feature of hyperthyroidism?","Anxiety, insomnia, irritability.","Ansiedade."],["32ljlk1v4","What is a key psychiatric feature of hypothyroidism?","Depression, cognitive slowing.","Depressão."],["7j2vqk1bq","What is a key psychiatric feature of Cushing syndrome?","Depression, psychosis, mood swings.","Depressão e psicose."],["1fae6hkej","What is a key psychiatric feature of pancreatic cancer?","Depression (can precede diagnosis).","Depressão."],["swg5pmw5y","What is a key psychiatric feature of Huntington disease?","Depression, irritability, psychosis, suicide.","Depressão e suicídio."],["1qs8hugfa","What is a key psychiatric feature of Wilson disease?","Personality changes, depression, psychosis in young patients.","Alteração de personalidade em jovens."],["11tp8f1ac","What is a key psychiatric feature of frontal lobe lesions?","Disinhibition, apathy, personality change.","Desinibição e apatia."],["16j9py51n","What is the gold standard initial approach to an agitated psychiatric patient?","Verbal de-escalation first; then medications (antipsychotic or benzodiazepine) if needed.","Desescalada verbal primeiro."],["1vh4v8i1y","What is intermittent explosive disorder?","Recurrent impulsive aggressive outbursts out of proportion to provocation.","Explosões de raiva desproporcionais."],["1k9th55yz","What is kleptomania?","Recurrent failure to resist impulses to steal objects not needed.","Impulso de roubar."],["16k9wk41p","What is pyromania?","Deliberate fire setting for pleasure or relief of tension.","Impulso de atear fogo."],["1cmrg4f17","What is gambling disorder?","Persistent problematic gambling causing distress; treated with CBT; associated with dopamine agonists.","Jogo patológico."],["1btdn9c1x","What is the most common substance of abuse in adolescents?","Alcohol (then cannabis and nicotine/vaping).","Álcool."],["1g6wzcp1m","What is the screening tool for adolescent substance use?","CRAFFT questionnaire.","Questionário CRAFFT."]]},{"name":"Pharmacology","cards":[["1c5xg9sg8","Mechanism of SSRIs?","Inhibit serotonin reuptake (fluoxetine, sertraline, paroxetine, citalopram, escitalopram, fluvoxamine).","Inibem a recaptação de serotonina."],["1hmm7mzbe","Uses of SSRIs?","Depression, generalized anxiety, panic, OCD, PTSD, bulimia, social anxiety, PMDD.","Depressão e ansiedade."],["xne2a5vk1","Adverse effects of SSRIs?","GI upset, sexual dysfunction (anorgasmia, decreased libido), SIADH, increased suicidality in young patients early, serotonin syndrome, QT prolongation (citalopram), bleeding risk.","Disfunção sexual, náusea, SIADH."],["1o4i25ldw","Which SSRI has the longest half-life and least discontinuation syndrome?","Fluoxetine.","Fluoxetina."],["9vbkkvb1t","Which SSRI is most anticholinergic and associated with discontinuation syndrome?","Paroxetine (avoid in pregnancy: cardiac defects).","Paroxetina."],["1tgvept1q","Which SSRI prolongs QT in a dose-dependent manner?","Citalopram.","Citalopram."],["be1g9v6yi","What is SSRI discontinuation syndrome?","Flu-like symptoms, dizziness, irritability, paresthesias (brain zaps) after abrupt cessation of short half-life SSRIs.","Sintomas ao parar abruptamente."],["1pexlj228","What is the black box warning of antidepressants?","Increased suicidal thoughts in children, adolescents, and young adults (<25).","Risco de suicídio em jovens."],["1bxcda5fx","Mechanism of SNRIs?","Inhibit serotonin and norepinephrine reuptake (venlafaxine, desvenlafaxine, duloxetine, levomilnacipran, milnacipran).","Inibem serotonina e noradrenalina."],["1h4bzquat","Uses of SNRIs?","Depression, generalized anxiety, diabetic neuropathy, fibromyalgia (duloxetine, milnacipran).","Depressão e dor neuropática."],["xdbmkwv7e","Adverse effects of SNRIs?","Increased BP (venlafaxine), stimulant effects, sedation, nausea, sexual dysfunction.","Aumento da pressão."],["sqzcqs1yo","Mechanism of tricyclic antidepressants?","Inhibit NE and serotonin reuptake; also block muscarinic, alpha1, and H1 receptors (amitriptyline, nortriptyline, imipramine, clomipramine, desipramine, doxepin).","Inibem recaptação e bloqueiam vários receptores."],["rb7rom1sr","Uses of TCAs?","Depression, neuropathic pain, migraine prophylaxis, OCD (clomipramine), enuresis (imipramine), insomnia (doxepin).","Dor neuropática e enurese."],["7n2ghssy9","Adverse effects of TCAs?","Sedation, alpha1 blockade (orthostatic hypotension), anticholinergic effects; tertiary amines more anticholinergic.","Sedação, hipotensão, efeitos anticolinérgicos."],["6pqcb21lp","What are the 3 Cs of TCA toxicity?","Convulsions, Coma, Cardiotoxicity (wide QRS, arrhythmia); also respiratory depression, hyperpyrexia.","Convulsões, coma, cardiotoxicidade."],["t25dqq25f","Treatment of TCA overdose?","Sodium bicarbonate (for wide QRS and to prevent arrhythmia).","Bicarbonato de sódio."],["xi9s8l9kz","Which TCA is preferred in elderly due to fewer side effects?","Nortriptyline (secondary amine, less anticholinergic).","Nortriptilina."],["15njdz011","Mechanism of MAO inhibitors?","Nonselective MAO inhibition increasing NE, serotonin, dopamine (tranylcypromine, phenelzine, isocarboxazid, selegiline transdermal).","Inibem a monoamina oxidase."],["1qt5d7bfu","Uses of MAO inhibitors?","Atypical depression, anxiety, treatment-resistant depression.","Depressão atípica."],["18yg01ozc","Adverse effects of MAOIs?","Hypertensive crisis with tyramine (aged cheese, wine), serotonin syndrome with other serotonergic drugs; wait 2 weeks between MAOI and SSRI (5 weeks for fluoxetine).","Crise hipertensiva com tiramina."],["1nny6pdj5","Mechanism and uses of bupropion?","Increases NE and dopamine (unknown mechanism, inhibits reuptake); depression, smoking cessation, ADHD.","Noradrenalina e dopamina; parar de fumar."],["330b0n1uv","Adverse effects of bupropion?","Stimulant effects, tachycardia, insomnia, headache, seizures (contraindicated in bulimia and anorexia); no sexual side effects.","Convulsões; sem efeito sexual."],["7igt7d17e","Mechanism and uses of mirtazapine?","Alpha2 antagonist (increases NE and 5-HT release) and potent 5-HT2 and 5-HT3 antagonist, H1 antagonist; depression with insomnia, poor appetite.","Antagonista alfa-2; sono e apetite."],["18xc71r1k","Adverse effects of mirtazapine?","Sedation, increased appetite, weight gain, dry mouth.","Sedação e ganho de peso."],["4cbkxvnf1","Mechanism and uses of trazodone?","Primarily blocks 5-HT2, alpha1, and H1 receptors; weakly inhibits serotonin reuptake; insomnia (low dose), depression.","Usado para insônia."],["jll7dj1fk","Adverse effects of trazodone?","Priapism, sedation, orthostatic hypotension.","Priapismo."],["jpxi661dg","Mechanism and use of vilazodone and vortioxetine?","Serotonin reuptake inhibitors with additional serotonin receptor activity; major depression.","Antidepressivos multimodais."],["me4kne1s5","Mechanism of esketamine?","NMDA receptor antagonist; nasal spray for treatment-resistant depression and suicidality.","Antagonista NMDA intranasal."],["fgv4lv1ib","Mechanism of brexanolone and zuranolone?","GABA-A positive allosteric modulators (neurosteroids); postpartum depression.","Neuroesteroides para depressão pós-parto."],["1ctbwmznz","Mechanism and uses of lithium?","Unclear (inhibits inositol recycling, affects phosphoinositide cascade); bipolar disorder mood stabilizer, suicide prevention.","Estabilizador do humor."],["1g3o3ilvt","Adverse effects of lithium?","Tremor, hypothyroidism, polyuria (nephrogenic DI), teratogenesis (Ebstein anomaly), weight gain, hyperparathyroidism, acne (LMNOP: Lithium side effects Movement, Nephrogenic DI, hypOthyroidism, Pregnancy problems).","Tremor, hipotireoidismo, diabetes insípido."],["kd3m7xby1","Why does lithium have a narrow therapeutic index?","Toxicity occurs just above therapeutic levels; requires monitoring of levels, renal and thyroid function.","Janela terapêutica estreita."],["1ef0uop1u","Which drugs increase lithium levels?","Thiazides, ACE inhibitors, ARBs, NSAIDs (decrease renal clearance), dehydration.","Tiazídicos, IECA, AINEs."],["1ns1aebvl","Mechanism of buspirone?","Partial 5-HT1A agonist; generalized anxiety disorder; no sedation, addiction, or tolerance; takes 1-2 weeks.","Ansiolítico sem dependência."],["10x1uz7xa","Mechanism of typical antipsychotics?","Block D2 receptors (high potency: haloperidol, fluphenazine; low potency: chlorpromazine, thioridazine).","Bloqueiam D2."],["14sxovs1e","Uses of typical antipsychotics?","Schizophrenia (positive symptoms), delirium, acute psychosis, bipolar disorder, Tourette syndrome, Huntington chorea.","Psicose e delirium."],["1fkbuv1t2","Adverse effects of high-potency typical antipsychotics?","Extrapyramidal symptoms (dystonia, akathisia, parkinsonism, tardive dyskinesia), hyperprolactinemia, neuroleptic malignant syndrome.","Sintomas extrapiramidais."],["cpcku5m6i","Adverse effects of low-potency typical antipsychotics?","Anticholinergic, antihistamine (sedation), alpha1 blockade (hypotension); chlorpromazine corneal deposits; thioridazine retinal deposits.","Sedação e hipotensão."],["ofup321yu","What is the timeline of extrapyramidal symptoms?","4 hours acute dystonia, 4 days akathisia, 4 weeks bradykinesia/parkinsonism, 4 months tardive dyskinesia.","4 horas, 4 dias, 4 semanas, 4 meses."],["1pnreea1n","Treatment of acute dystonia?","Benztropine or diphenhydramine.","Biperideno ou difenidramina."],["v2pyk21vp","Treatment of akathisia?","Propranolol, benzodiazepines, reduce dose.","Propranolol."],["14d5582lo","Treatment of tardive dyskinesia?","Switch to clozapine or quetiapine; VMAT2 inhibitors (valbenazine, deutetrabenazine).","Valbenazina."],["oxk0fm1rn","Mechanism of atypical antipsychotics?","Block 5-HT2A and D2 receptors (aripiprazole, quetiapine, risperidone, olanzapine, clozapine, ziprasidone, lurasidone).","Bloqueiam 5-HT2A e D2."],["1t84d6h1g","Uses of atypical antipsychotics?","Schizophrenia (positive and negative symptoms), bipolar disorder, OCD, agitation, depression adjunct, Tourette syndrome.","Esquizofrenia e bipolar."],["1eez9jz1g","Adverse effects of atypical antipsychotics?","Metabolic syndrome (weight gain, diabetes, dyslipidemia; olanzapine and clozapine worst), QT prolongation, fewer EPS.","Síndrome metabólica."],["17czxix3s","Which atypical antipsychotic causes agranulocytosis?","Clozapine (monitor ANC); also seizures, myocarditis, sialorrhea.","Clozapina."],["ez9rqy10r","When is clozapine used?","Treatment-resistant schizophrenia and to reduce suicide risk in schizophrenia.","Esquizofrenia resistente."],["1wtwwl6an","Which atypical antipsychotic causes hyperprolactinemia?","Risperidone (galactorrhea, amenorrhea, gynecomastia).","Risperidona."],["rqhmbe1em","Which atypical antipsychotic prolongs QT most?","Ziprasidone.","Ziprasidona."],["dlz742bul","Which antipsychotic is a D2 partial agonist?","Aripiprazole (also brexpiprazole, cariprazine): lower metabolic risk; akathisia.","Aripiprazol."],["18ksv1n12","Which antipsychotic is preferred in Parkinson disease psychosis?","Pimavanserin, quetiapine, clozapine.","Pimavanserina."],["rkszrz1qh","What are long-acting injectable antipsychotics used for?","Patients with poor adherence (haloperidol decanoate, paliperidone palmitate, aripiprazole).","Pacientes com má adesão."],["2z7406he2","Mechanism of benzodiazepines?","Increase frequency of GABA-A chloride channel opening.","Aumentam a abertura do canal de cloreto."],["1qvxcyj1d","Which benzodiazepines are short acting?","Triazolam, oxazepam, midazolam (higher addictive potential).","Triazolam e midazolam."],["bmbvi91u7","Which benzodiazepines are safe in liver disease?","Lorazepam, oxazepam, temazepam (glucuronidation only; Outside The Liver).","Lorazepam, oxazepam, temazepam."],["iu6vqjcq0","Adverse effects of benzodiazepines?","Dependence, additive CNS depression with alcohol, anterograde amnesia, falls in elderly.","Dependência e quedas."],["1ys0bwq2o","Mechanism and use of barbiturates?","Increase duration of GABA-A channel opening; sedation, seizures, anesthesia; contraindicated in porphyria.","Aumentam a duração da abertura."],["5fgznz1rf","Mechanism and uses of methylphenidate and amphetamines?","Increase catecholamines in the synaptic cleft (block reuptake, increase release); ADHD, narcolepsy, binge eating disorder (lisdexamfetamine).","Estimulantes."],["8jd0s7ei0","Adverse effects of stimulants?","Nervousness, insomnia, decreased appetite, weight loss, tachycardia, hypertension, growth suppression, addiction.","Insônia e perda de apetite."],["x9wxar11q","Mechanism and use of atomoxetine?","Selective norepinephrine reuptake inhibitor; ADHD (nonstimulant, no abuse potential).","TDAH sem estimulante."],["1f998n3dm","Mechanism and use of guanfacine and clonidine in ADHD?","Alpha2 agonists; ADHD (especially with tics), Tourette.","TDAH com tiques."],["16t4lm41w","Mechanism and use of naltrexone in addiction?","Opioid antagonist; alcohol use disorder (reduces cravings), opioid use disorder (after detox).","Reduz o desejo de beber."],["102zpk016","Mechanism and use of acamprosate?","NMDA receptor modulator; alcohol use disorder; safe in liver disease, avoid in renal failure.","Seguro na doença hepática."],["3jdely1y9","Mechanism and use of disulfiram?","Inhibits aldehyde dehydrogenase; aversive therapy for alcohol use disorder.","Reação desagradável com álcool."],["1d6ptc418","Mechanism and use of buprenorphine-naloxone?","Partial opioid agonist with naloxone to deter IV misuse; opioid use disorder.","Buprenorfina com naloxona."],["z74d4a8mh","Mechanism and use of varenicline?","Nicotinic partial agonist; smoking cessation.","Vareniclina para parar de fumar."],["1quzfwy1q","What drug is used for alcohol withdrawal prevention in liver failure?","Lorazepam or oxazepam.","Lorazepam."],["lrxasl11y","Which antidepressant is safest in heart disease?","SSRIs (sertraline).","Sertralina."],["pkwsi3133","Which antidepressant is preferred in pregnancy?","Sertraline (most data).","Sertralina."],["1t7pcyf18","Which antidepressant causes priapism?","Trazodone.","Trazodona."],["ho7pql1pc","Which antidepressant lowers seizure threshold most?","Bupropion.","Bupropiona."],["1p5iiod8j","Which antidepressant has the least sexual side effects?","Bupropion and mirtazapine.","Bupropiona e mirtazapina."],["t9eg77ozz","Which antidepressant also treats neuropathic pain and fibromyalgia?","Duloxetine (SNRI) and TCAs.","Duloxetina."],["1xcppb01e","Which antidepressant is used for nocturnal enuresis?","Imipramine.","Imipramina."],["1ao3s5dlc","Which antidepressant is used for OCD besides SSRIs?","Clomipramine.","Clomipramina."],["1l8g33whf","What is serotonin syndrome's classic triad?","Mental status changes, autonomic instability (hyperthermia, tachycardia), neuromuscular abnormalities (clonus, hyperreflexia).","Confusão, instabilidade autonômica, clônus."],["10jjid71k","Treatment of serotonin syndrome?","Stop serotonergic drugs, benzodiazepines, cyproheptadine, cooling.","Suspender e ciproeptadina."],["14eofstd5","Treatment of neuroleptic malignant syndrome?","Stop antipsychotic, supportive care, dantrolene, bromocriptine.","Dantroleno e bromocriptina."],["uu6th01ix","What is the lab finding in neuroleptic malignant syndrome?","Very high CK, leukocytosis, myoglobinuria.","CPK muito alta."],["yn2azv1uo","What should be monitored with atypical antipsychotics?","Weight, BMI, fasting glucose or A1c, lipids, BP.","Peso, glicose, lipídios."],["1ldd46xge","What should be monitored with lithium?","Serum lithium levels, TSH, creatinine, calcium, ECG.","Lítio, TSH e creatinina."],["b8ezzrkil","What should be monitored with valproate?","LFTs, CBC (platelets), drug levels, ammonia if symptomatic.","Função hepática e plaquetas."],["19m23xflf","What should be monitored with carbamazepine?","CBC, LFTs, sodium, drug levels.","Hemograma e sódio."],["35woig1lv","What should be monitored with clozapine?","Absolute neutrophil count, signs of myocarditis, seizures.","Neutrófilos."],["8z8412zrp","What is the mood stabilizer that is safest in pregnancy?","Lamotrigine (lithium has Ebstein risk; valproate and carbamazepine teratogenic).","Lamotrigina."],["1jxytq21g","What is the treatment for bipolar depression without inducing mania?","Quetiapine, lurasidone, lamotrigine, lithium, cariprazine.","Quetiapina e lamotrigina."],["m5m31p1im","What drug class is first line for generalized anxiety disorder?","SSRIs or SNRIs.","ISRS ou IRSN."],["17bpnpw1q","What drug class is used for acute panic attacks?","Benzodiazepines (short term).","Benzodiazepínicos."],["102evwio0","What drug is used for insomnia without dependence (melatonin agonist)?","Ramelteon.","Ramelteon."],["1nkd1qo3n","What drug is used for insomnia via orexin antagonism?","Suvorexant, lemborexant.","Suvorexanto."],["zmoxsv1tc","What drug class causes complex sleep behaviors (sleep driving)?","Nonbenzodiazepine hypnotics (zolpidem).","Zolpidem."],["j6d8bjst9","What drug class treats nightmares in PTSD?","Prazosin (alpha1 blocker).","Prazosina."],["14eskr7d1","Which medication is approved for tardive dyskinesia?","Valbenazine and deutetrabenazine.","Valbenazina."],["1hsscto1e","Which antipsychotic has lowest metabolic risk?","Aripiprazole, ziprasidone, lurasidone.","Aripiprazol."],["1xud4051o","Which antipsychotics have highest metabolic risk?","Clozapine and olanzapine.","Clozapina e olanzapina."],["1ejk17mbl","What is the mechanism of haloperidol in delirium?","D2 blockade reducing agitation and psychosis.","Bloqueio D2."],["14mswp5i9","What is the risk of antipsychotics in elderly patients with dementia?","Increased mortality (stroke, cardiovascular).","Aumento de mortalidade."],["1hizb3v1q","What is the mechanism of lisdexamfetamine?","Prodrug of dextroamphetamine; ADHD and binge eating disorder.","Pró-droga de anfetamina."],["1kwpyj5re","Which drugs should be avoided with MAOIs?","SSRIs, SNRIs, TCAs, meperidine, tramadol, dextromethorphan, St. John's wort, sympathomimetics, tyramine-rich foods.","Serotoninérgicos e tiramina."],["39r4qs14v","What is the washout period from fluoxetine before starting an MAOI?","About 5 weeks (long half-life of norfluoxetine).","Cerca de 5 semanas."],["8nddibkbr","What is the effect of St. John's wort on drug metabolism?","Induces CYP3A4 (reduces OCPs, cyclosporine, warfarin) and can cause serotonin syndrome.","Induz CYP3A4."],["1ezc3rh18","What is the role of ECT in the elderly?","Safe and effective for severe or psychotic depression.","Seguro e eficaz."],["ssr1461yu","What is the treatment for catatonia?","Lorazepam; ECT if refractory.","Lorazepam."],["7hoqrl14d","Which antiepileptic is also used for bipolar depression maintenance?","Lamotrigine.","Lamotrigina."],["7unaprh07","Which drug treats alcohol cravings and is also used for migraine and weight loss?","Topiramate (off-label).","Topiramato."],["13vvg8lnd","Which drug is used as a long-acting injectable for opioid use disorder?","Extended-release naltrexone or buprenorphine depot.","Naltrexona de depósito."],["euw6kq7iz","Which drug is used for opioid withdrawal symptoms without opioid action?","Clonidine or lofexidine.","Clonidina ou lofexidina."],["1jzdlsr2x","What is the treatment for antidepressant-induced sexual dysfunction?","Switch to bupropion or mirtazapine, add bupropion, or PDE5 inhibitors.","Trocar para bupropiona."]]},{"name":"Psychology","cards":[["2uv5o01jb","What is classical conditioning?","Learning in which a natural response is elicited by a conditioned stimulus that was previously paired with an unconditioned stimulus (Pavlov's dogs).","Condicionamento clássico."],["p3f9hmlw3","What is operant conditioning?","Learning in which a voluntary behavior is modified by reinforcement or punishment.","Condicionamento operante."],["eb5zgeti1","What is positive reinforcement?","Desired reward increases a behavior (praise for good grades).","Recompensa aumenta o comportamento."],["1b9fit217","What is negative reinforcement?","Removal of an aversive stimulus increases a behavior (seat belt beep stops when buckled).","Remover algo ruim aumenta o comportamento."],["bcs2a21cf","What is positive punishment?","Adding an aversive stimulus decreases a behavior.","Acrescentar algo ruim diminui."],["fce9mqygp","What is negative punishment?","Removing a desired stimulus decreases a behavior (taking away a toy).","Retirar algo bom diminui."],["1mmqnqzwy","What is extinction?","Discontinuation of reinforcement eventually eliminates a behavior; extinction burst may occur first.","Extinção."],["h7cc7t1m7","Which reinforcement schedule is most resistant to extinction?","Variable ratio (slot machines).","Razão variável."],["1974scwtq","Which reinforcement schedule causes rapid extinction?","Continuous reinforcement (vending machine).","Reforço contínuo."],["1pvw86k1u","What is transference?","Patient projects feelings about significant others onto the physician.","Paciente projeta sentimentos no médico."],["17df988w1","What is countertransference?","Physician projects feelings about significant others onto the patient.","Médico projeta sentimentos no paciente."],["wpox4yu8a","What are ego defenses?","Mostly unconscious thoughts or behaviors used to resolve conflict and prevent anxiety.","Mecanismos de defesa."],["6nu6oi1uw","What is acting out?","Subconsciously coping with stressors or emotional conflict using actions rather than reflections or feelings (tantrums).","Atuação."],["1iiijb513","What is denial?","Avoiding awareness of some painful reality (cancer patient insists diagnosis is wrong).","Negação."],["mnkxul30c","What is displacement?","Redirection of emotions or impulses to a neutral person or object (yelling at spouse after a bad day at work).","Deslocamento."],["w2y39b1to","What is dissociation?","Temporary drastic change in personality, memory, consciousness, or motor behavior to avoid emotional stress.","Dissociação."],["lwmf4wcn6","What is fixation?","Partially remaining at a more childish level of development (biting fingernails).","Fixação."],["1ax916o1w","What is identification?","Largely unconscious assumption of characteristics of a more powerful person (abused child becomes abuser).","Identificação."],["qeyn4kbkt","What is isolation of affect?","Separation of feelings from ideas and events (describing a murder in detail without emotion).","Isolamento do afeto."],["k96pxzs7i","What is projection?","Attributing an unacceptable internal impulse to an external source (a man who wants to cheat accuses his wife of cheating).","Projeção."],["12ot1bap4","What is rationalization?","Asserting plausible explanations for events that occurred for other reasons (saying a job was not important after being fired).","Racionalização."],["ur7aso1ri","What is reaction formation?","Replacing a warded-off idea or feeling with an emphasis on its opposite (a patient with sexual urges joins a monastery).","Formação reativa."],["16vm21x1j","What is regression?","Involuntary return to earlier developmental behaviors in stress (bedwetting in a hospitalized child).","Regressão."],["b3pywizgq","What is repression?","Involuntary withholding of an idea or feeling from conscious awareness (not remembering a traumatic event).","Repressão involuntária."],["k1n3cc19r","What is splitting?","Believing people are either all good or all bad; common in borderline personality disorder.","Divisão: tudo bom ou tudo mau."],["1izevx41w","What is intellectualization?","Using facts and logic to emotionally distance oneself from a stressful situation.","Intelectualização."],["mwyf5r1vu","What is passive aggression?","Demonstrating hostile feelings in a nonconfrontational manner (being late on purpose).","Agressão passiva."],["1gcdtruzx","What is undoing?","Performing acts to counteract unacceptable thoughts (OCD rituals).","Anulação."],["ud1tk3w53","What are mature ego defenses?","Sublimation, altruism, suppression, humor (SASH).","Defesas maduras."],["nmb8nv10d","What is sublimation?","Replacing an unacceptable wish with a socially acceptable action (aggression channeled into sports).","Sublimação."],["y7d6bn12p","What is altruism?","Alleviating guilt by helping others (a mafia boss donating to charity).","Altruísmo."],["10bpvn71k","What is suppression?","Intentional withholding of an idea from consciousness (choosing not to think about exam results until after the weekend).","Supressão voluntária."],["1o6ic327f","What is humor as a defense?","Appreciating the amusing nature of an anxiety-provoking situation.","Humor."],["uqszk416l","What is the difference between repression and suppression?","Repression is unconscious; suppression is conscious and mature.","Inconsciente versus consciente."],["1l28t9h1o","What is the cognitive behavioral therapy approach?","Identifying and changing maladaptive thoughts and behaviors; effective for depression, anxiety, OCD, insomnia, eating disorders.","Muda pensamentos e comportamentos."],["1a2x40t43","What is dialectical behavioral therapy?","CBT variant teaching emotional regulation and distress tolerance; designed for borderline personality disorder.","Terapia para personalidade borderline."],["hyu5221nr","What is exposure therapy?","Gradual exposure to feared stimuli (systematic desensitization) for phobias and PTSD.","Exposição gradual."],["ik6jtjlak","What is exposure and response prevention?","CBT for OCD: exposure to obsessions while preventing compulsions.","Exposição com prevenção de resposta."],["1fjusxmww","What is motivational interviewing?","Client-centered counseling to resolve ambivalence and enhance motivation (substance use).","Entrevista motivacional."],["lxiikc1e5","What is psychodynamic psychotherapy?","Explores unconscious conflicts and past experiences shaping current behavior.","Psicoterapia psicodinâmica."],["1tkfnmd9a","What is interpersonal therapy?","Focuses on improving relationships and communication; effective for depression.","Terapia interpessoal."],["8nlevbp81","What is biofeedback?","Using information about physiologic processes (heart rate, muscle tension) to gain voluntary control; migraine, tension headaches.","Biofeedback."],["1a43gxg1q","What is the Kübler-Ross model of grief?","Denial, anger, bargaining, depression, acceptance (not necessarily in order).","Negação, raiva, barganha, depressão, aceitação."],["149hlqes8","What is normal grief?","Shock, denial, guilt, sadness, anxiety, yearning; may include brief hallucinations of the deceased; usually improves within 6-12 months.","Luto normal."],["1aq65hfnk","What is prolonged grief disorder?","Persistent intense grief interfering with function for more than 12 months (6 months in children).","Luto prolongado."],["ln1pkf6c5","What is the difference between grief and major depression?","Grief: waves of sadness focused on the loss, self-esteem preserved. Depression: pervasive, worthlessness, suicidal ideation.","Luto mantém a autoestima."],["oql1rf8c3","What are Piaget's stages?","Sensorimotor (0-2), preoperational (2-7), concrete operational (7-11), formal operational (12+).","Estágios de Piaget."],["yzxfe4181","What is Freud's structural model?","Id (primal urges), ego (mediator, reality), superego (moral values, conscience).","Id, ego e superego."],["jjx7te1iq","What is Maslow's hierarchy of needs?","Physiological, safety, love/belonging, esteem, self-actualization.","Pirâmide de Maslow."],["1m8n1t8nw","What is learned helplessness?","Repeated failure to escape adverse situations leads to passivity; model for depression.","Desamparo aprendido."],["12efp831f","What is the placebo effect in psychiatry?","Improvement from expectation alone; high in depression trials.","Efeito placebo."],["19xnnrd1v","What is habituation vs sensitization?","Habituation: decreased response to repeated stimulus. Sensitization: increased response.","Habituação diminui; sensibilização aumenta."],["8uuz56ten","What is the Yerkes-Dodson law?","Moderate arousal optimizes performance; too little or too much impairs it.","Ansiedade moderada melhora o desempenho."],["1nxbkd4ti","What is primary vs secondary gain?","Primary gain: internal psychological benefit of symptoms. Secondary gain: external benefits (attention, avoiding work).","Ganho primário interno; secundário externo."],["1t3cgrjmh","What is tertiary gain?","Benefit to others (caregivers) from a patient's illness.","Ganho de terceiros."],["1l4jjtu1q","What is the Mini-Mental State Examination used for?","Screening cognitive impairment (orientation, recall, attention, language, visuospatial).","Rastreio cognitivo."],["o9msf9z4n","What is the Montreal Cognitive Assessment?","Screening for mild cognitive impairment (more sensitive than MMSE).","Teste MoCA."],["48o1se1ib","What is the PHQ-9?","Depression screening and severity questionnaire.","Rastreio de depressão."],["1sca2q312","What is the GAD-7?","Generalized anxiety disorder screening questionnaire.","Rastreio de ansiedade."],["1k4kigc1p","What is the CAGE questionnaire?","Alcohol use screen: Cut down, Annoyed, Guilty, Eye-opener.","Rastreio de álcool."],["rk5f3k4ro","What is the AUDIT-C?","Alcohol use disorders screening tool.","Rastreio de álcool."],["1lz1pob77","What is the SAD PERSONS scale?","Suicide risk factors: Sex (male), Age, Depression, Previous attempt, Ethanol, Rational thinking loss, Sickness, Organized plan, No spouse, Social support lacking.","Fatores de risco de suicídio."],["14ruj5b18","What is the strongest predictor of suicide?","Previous suicide attempt.","Tentativa prévia."],["15cciz314","Who completes suicide more often vs attempts more often?","Men complete more (more lethal means); women attempt more.","Homens completam; mulheres tentam mais."],["115c01o1m","What is the most common method of completed suicide in the US?","Firearms.","Armas de fogo."],["cdvjnp1js","What is the appropriate response to a patient with suicidal ideation?","Ask directly about plan, intent, means; ensure safety; hospitalize if high risk.","Perguntar diretamente sobre plano."],["a79h2h1nj","Does asking about suicide increase the risk?","No.","Não."],["1vg3abzi9","What is the difference between malingering and factitious disorder?","Malingering: conscious faking for external gain. Factitious: conscious faking for primary gain (sick role).","Ganho externo versus papel de doente."],["14ystxg1s","What is the difference between factitious and somatic symptom disorders?","Factitious: intentionally produced symptoms. Somatic symptom: not intentional; real distress.","Intencional versus não intencional."],["p5iv6qetv","What is the role of the therapeutic alliance?","Collaborative relationship between patient and clinician; best predictor of therapy outcome.","Aliança terapêutica."],["7kq2ec15a","What is the stages of change model?","Precontemplation, contemplation, preparation, action, maintenance, relapse.","Estágios de mudança."],["1hcv79715","What is the role of family therapy?","Addresses family dynamics; used in eating disorders (Maudsley approach for anorexia).","Terapia familiar."],["1tfsh3l1u","What is group therapy useful for?","Substance use disorders, PTSD, social anxiety; peer support.","Terapia de grupo."],["vuu5by2xk","What is eye movement desensitization and reprocessing?","Therapy for PTSD using bilateral stimulation while recalling trauma.","Terapia EMDR para TEPT."],["llb7fz1k7","What is mindfulness-based therapy?","Focus on present-moment awareness; reduces relapse in depression and anxiety.","Atenção plena."],["vuzg3y130","What is a common sleep hygiene principle?","Consistent sleep schedule, avoid screens and caffeine before bed, bed for sleep only.","Higiene do sono."],["tmzuuc2cl","What is intelligence quotient (IQ) and intellectual disability?","IQ mean 100, SD 15; intellectual disability is IQ <70 with deficits in adaptive functioning before 18.","QI abaixo de 70 com prejuízo adaptativo."],["lfp3c0yrk","What are the severity levels of intellectual disability?","Mild (IQ 50-70), moderate (35-49), severe (20-34), profound (<20).","Leve, moderada, grave e profunda."],["1to0btw1p","What is the most common genetic cause of intellectual disability?","Down syndrome (fragile X is the most common inherited cause).","Síndrome de Down."],["7gupag1yl","What is the Wechsler test used for?","Measuring IQ (WAIS adults, WISC children).","Teste de QI."],["1c9v4ib1t","What is projective testing?","Interpreting responses to ambiguous stimuli (Rorschach, Thematic Apperception Test).","Testes projetivos."],["17pzlfony","What is the Minnesota Multiphasic Personality Inventory?","Objective personality test with true/false items.","Teste objetivo de personalidade."],["1yp17hh11","What is the role of cultural factors in psychiatric diagnosis?","Symptoms must be evaluated in cultural context; some experiences are normal within certain cultures.","Considerar o contexto cultural."],["s9aco51hl","What is a culture-bound syndrome example?","Ataque de nervios, koro, amok.","Síndromes ligadas à cultura."],["1hlpxxd14","What is the defense mechanism of a medical student who jokes about death?","Humor.","Humor."],["mw5apn8d5","What is the defense mechanism of a patient angry at a nurse after bad news from a doctor?","Displacement.","Deslocamento."],["1czsxqy19","What is the defense mechanism of a patient who insists on all details of their surgery to avoid fear?","Intellectualization.","Intelectualização."],["olkfn41k1","What is the defense mechanism of an adult who sucks their thumb when stressed?","Regression.","Regressão."],["1sqqhv936","What is the defense mechanism of a patient idealizing one doctor and devaluing another?","Splitting.","Divisão."],["v3re39p6p","What is the defense mechanism of a man attracted to his coworker who becomes very rude to her?","Reaction formation.","Formação reativa."],["1psrsl11k","What is the defense mechanism of a man with no memory of childhood abuse?","Repression.","Repressão."],["9zixy8u7k","What is the defense mechanism of a teen who decides to stop thinking about a breakup until after exams?","Suppression.","Supressão."],["xafek16ns","What is the defense mechanism of a surgeon channeling aggression into surgery?","Sublimation.","Sublimação."],["11yejtm1i","What is the defense mechanism of an alcoholic insisting they do not have a drinking problem?","Denial.","Negação."],["191pisw1w","What is the defense mechanism of a student who failed and blames the test being unfair?","Rationalization (or projection depending on context).","Racionalização."],["42ohcp6s8","What is the defense mechanism of an OCD patient who repeatedly washes hands after an unacceptable thought?","Undoing.","Anulação."],["17t0zc1mw","What is the defense mechanism of a patient describing their wife's death calmly with no emotion?","Isolation of affect.","Isolamento do afeto."],["1dbf54r1i","What is the defense mechanism of a person who acts in an aggressive way like their abusive parent?","Identification (with the aggressor).","Identificação com o agressor."],["xsj3u1b0h","What is the defense mechanism of a person who copes with anxiety by having a temper tantrum?","Acting out.","Atuação."],["1tbue9311","What is the defense mechanism of a patient who feels detached from their body during trauma?","Dissociation.","Dissociação."]]}];
